const fs = require('fs');
const path = require('path');
const STATE_PATH = path.join(__dirname, '..', 'state', 'incidents.json');

function loadIncidents() {
  return JSON.parse(fs.readFileSync(STATE_PATH, 'utf8'));
}

function renderOperatorView() {
  const s = loadIncidents();
  const lines = s.openIncidents.map((i) => i.id + ' (' + i.severity + '): ' + i.summary);
  return 'Service: ' + s.service + '\n' + lines.join('\n');
}

module.exports = { loadIncidents, renderOperatorView };

